/**
 * What dictation reports, in order.
 */
sealed class DictationEvent {
    
    /**
     * Listening: the stream is open.
     */
    object Connected : DictationEvent()
    
    
    /**
     * All the not-yet-final text so far; it replaces the previous partial.
     */
    data class Partial(
        val `text`: kotlin.String) : DictationEvent()
        
    {
        

        companion object
    }
    
    /**
     * A finished piece of text, in order; it replaces the partial it came from.
     */
    data class Final(
        val `text`: kotlin.String) : DictationEvent()
        
    {
        

        companion object
    }
    
    /**
     * Microphone peak, 0…1, about 12 a second while audible.
     */
    data class Levels(
        val `mic`: kotlin.Float) : DictationEvent()
        
    {
        

        companion object
    }
    
    /**
     * Dictation ended ("stopped" after `stop`, "cancelled" after `cancel`, else why).
     * Nothing follows it.
     */
    data class Closed(
        val `reason`: kotlin.String) : DictationEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
