                FfiConverterString.read(buf),
                )
            3 -> DictationEvent.Final(
                FfiConverterString.read(buf),
                )
            4 -> DictationEvent.Levels(
                FfiConverterFloat.read(buf),
                )
            5 -> DictationEvent.Closed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DictationEvent): ULong = when(value) {
        is DictationEvent.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DictationEvent.Partial -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is DictationEvent.Final -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
